import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import { usePolicies, Policy } from '@/hooks/usePolicies';

interface PolicyEditorProps {
  policy: Policy | null;
  onClose: () => void;
}

export const PolicyEditor: React.FC<PolicyEditorProps> = ({ policy, onClose }) => {
  const { addPolicy, updatePolicy } = usePolicies();
  const [formData, setFormData] = useState<Partial<Policy>>({
    name: '',
    description: '',
    effect: 'allow',
    rules: []
  });

  useEffect(() => {
    if (policy) {
      setFormData(policy);
    } else {
      setFormData({ name: '', description: '', effect: 'allow', rules: [] });
    }
  }, [policy]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (policy?.id) {
        await updatePolicy.mutateAsync({ id: policy.id, ...formData });
      } else {
        await addPolicy.mutateAsync(formData as Omit<Policy, 'id' | 'created_at'>);
      }
      onClose();
    } catch (err) {
      console.error('Erro ao salvar policy:', err);
    }
  };

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>{policy ? 'Editar Política' : 'Nova Política'}</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">Nome</Label>
            <Input 
              id="name" 
              value={formData.name || ''} 
              onChange={e => setFormData({ ...formData, name: e.target.value })} 
              required 
            />
          </div>
          <div className="space-y-2">
            <Label htmlFor="effect">Efeito</Label>
            <select 
              id="effect" 
              className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
              value={formData.effect}
              onChange={e => setFormData({ ...formData, effect: e.target.value as 'allow' | 'deny' })}
            >
              <option value="allow">Permitir (Allow)</option>
              <option value="deny">Bloquear (Deny)</option>
            </select>
          </div>
          <div className="space-y-2">
            <Label htmlFor="description">Descrição</Label>
            <Textarea 
              id="description" 
              value={formData.description || ''} 
              onChange={e => setFormData({ ...formData, description: e.target.value })} 
            />
          </div>
          <div className="flex justify-end gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose}>Cancelar</Button>
            <Button type="submit" disabled={addPolicy.isPending || updatePolicy.isPending}>
              Salvar
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
};

