import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Textarea } from '@/shared/ui/textarea';
import { usePolicies } from '@/hooks/usePolicies';
import type { Policy } from '@/types/policies';

interface PolicyEditorProps {
  policy: Policy | null;
  onClose: () => void;
}

export function PolicyEditor({ policy, onClose }: PolicyEditorProps) {
  const { addPolicy, updatePolicy } = usePolicies();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<Partial<Policy>>({
    name: '',
    description: '',
    effect: 'allow',
    rules: []
  });

  useEffect(() => {
    if (policy) {
      setFormData(policy);
    }
  }, [policy]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (policy?.id) {
        await updatePolicy(policy.id, formData);
      } else {
        await addPolicy(formData);
      }
      onClose();
    } catch (error) {
      console.error('Erro ao salvar policy:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>{policy ? 'Editar Política' : 'Nova Política'}</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="name">Nome</Label>
            <Input
              id="name"
              value={formData.name || ''}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="effect">Efeito</Label>
            <select
              id="effect"
              className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
              value={formData.effect || 'allow'}
              onChange={(e) => setFormData({ ...formData, effect: e.target.value as 'allow' | 'deny' })}
            >
              <option value="allow">Permitir (Allow)</option>
              <option value="deny">Bloquear (Deny)</option>
            </select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Descrição</Label>
            <Textarea
              id="description"
              value={formData.description || ''}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
          </div>

          <div className="flex justify-end gap-2 pt-4">
            <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
              Cancelar
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Salvando...' : 'Salvar Políitica'}
            </Button>
          </div>
        </form>
      </CardContent>
    </Card>
  );
}

